-- Apply after schema.sql on a new project.
create table if not exists public.qj_lessons (id text primary key,title text not null,paper integer not null check(paper in(1,2)),summary text not null,formula text not null,trap text not null,tip text not null);
alter table public.qj_lessons enable row level security;
grant select on public.qj_lessons to anon,authenticated;
grant all on public.qj_lessons to service_role;
create policy qj_lessons_read on public.qj_lessons for select to anon,authenticated using(true);
on conflict(id) do update set title=excluded.title,paper=excluded.paper,summary=excluded.summary,formula=excluded.formula,trap=excluded.trap,tip=excluded.tip;
